// Synthetic dataset for tests and local demos. Not real business data: generated by anonymising
// the original Excel import (names, values, file names replaced) so tests keep realistic shapes.
import documents from './documents.json';
import contracts from './contracts.json';
import partners from './partners.json';
import type { SeedDataset } from '../../src/server/db/seed.ts';
import { defaultUsers } from '../../src/server/db/persistence.ts';

// Test accounts: same ids/roles as the bootstrap accounts, but with passwords that are not the
// published defaults (logging in with a default password forces a password change).
export const TEST_ADMIN_PASSWORD = 'AdminTest@2026';
export const TEST_USER_PASSWORD = 'UserTest@2026';

export const fixtureDataset: SeedDataset = {
  documents: documents as any,
  contracts: contracts as any,
  partners: partners as any,
  users: defaultUsers.map((u) => ({
    ...u,
    password: u.username === 'admin' ? TEST_ADMIN_PASSWORD : TEST_USER_PASSWORD,
    must_change_password: false,
  })),
};
